import React from 'react';
import { Maximize2, Minimize2, PlusCircle, ChevronRight } from 'lucide-react';
import { RenderMainContentParams } from '../BaseDashboardLayout'; // Import RenderMainContentParams
import { QuickBoardPlugin } from './types'; // Import the QuickBoardPlugin interface

// Placeholder plugin components
const SupplierDashboardPlugin: React.FC<any> = () => (
  <div>
    <h3>Supplier Dashboard Content</h3>
    <p>This is content for the supplier role.</p>
  </div>
);

const CustomerAnalyticsPlugin: React.FC<any> = () => (
  <div>
    <h3>Customer Analytics Content</h3>
    <p>This is content for the customer role.</p>
  </div>
);

interface QuickBoardComponentProps {
  showCustomModal: RenderMainContentParams['showCustomModal'];
  plugins: QuickBoardPlugin[];
  userRoles: string[]; // User's roles
}

const QuickBoardComponent = ({ showCustomModal, plugins, userRoles }: QuickBoardComponentProps) => {
  const authorizedPlugins = plugins.filter(plugin =>
    plugin.roles.some(role => userRoles.includes(role))
  );

 return (
    <div className="flex flex-col gap-6">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">        {authorizedPlugins
          .map(plugin => (
            <div key={plugin.id} className="bg-white rounded-lg shadow-md">
              <div className="p-4 border-b flex justify-between items-center">
                <h2 className="font-semibold">{plugin.title}</h2>
                {/* Plugin-specific controls could go here or within the plugin component */}
 <div className="flex gap-1">
                  {/* Example: Maximize button could render the plugin component inside a modal */}
                  <button onClick={() => showCustomModal(<div>Minimize {plugin.title}</div>, `Minimize ${plugin.title}`)} className="p-1 rounded hover:bg-gray-100"><Minimize2 size={16} /></button>
                </div>
              </div>
              <div className="p-4">
                <plugin.component showCustomModal={showCustomModal} /> {/* Render the plugin component */}
              </div>
            </div>
          ))}
      </div>

      {/* Render 'full' layout plugins below the grid */}
      {authorizedPlugins
        .map(plugin => (
          <div key={plugin.id} className="bg-white rounded-lg shadow-md">
            <div className="p-4 border-b flex justify-between items-center">
              <h2 className="font-semibold">{plugin.title}</h2>
              {/* Plugin-specific controls */}
               <div className="flex gap-1">
                  {/* Basic Maximize/Minimize controls as examples */}
                  <button onClick={() => showCustomModal(<div>Minimize {plugin.title}</div>, `Minimize ${plugin.title}`)} className="p-1 rounded hover:bg-gray-100"><Minimize2 size={16} /></button>
              </div>
            </div>
            <div className="p-4">
              <plugin.component showCustomModal={showCustomModal} /> {/* Render the plugin component */}
            </div>
          </div>
        ))}
    </div>
  );
};

export default QuickBoardComponent;